import{_ as i,o as e,c as s,ae as t}from"./chunks/framework.BmsPYn1i.js";const k=JSON.parse('{"title":"モードについて","description":"","frontmatter":{},"headers":[],"relativePath":"FeaturesIntroduction/SetMode/index.md","filePath":"FeaturesIntroduction/SetMode/index.md"}'),l={name:"FeaturesIntroduction/SetMode/index.md"};function o(r,a,h,n,d,p){return e(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="モードについて" tabindex="-1">モードについて <a class="header-anchor" href="#モードについて" aria-label="Permalink to &quot;モードについて&quot;">​</a></h1><h2 id="モードとは" tabindex="-1">モードとは <a class="header-anchor" href="#モードとは" aria-label="Permalink to &quot;モードとは&quot;">​</a></h2><p>a3jsのオブジェクト（<code>ObjectA3</code>）は、<code>setMode()</code>で「モード」を 切り替えることで、位置・回転・拡大率をどう制御するかを変更でき ます。第2引数にはモードごとのオプションを渡せます。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">obj.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;SimplePhysics&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,{rigidBody:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fixed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>モードは大きく2つのグループに分かれます。</p><p><strong>プログラムで動きを決めるモード</strong> — <code>setPosition()</code>などで指定した 通りに（またはそれを加工して）動きます。</p><ul><li><a href="./Default.html">Defaultモード</a> — 指定した値を即座に反映します （初期モード）。</li><li><a href="./Smooth.html">Smoothモード</a> — 指定した値へ約1秒かけてなめらかに 補間します。</li><li><a href="./Follow.html">Followモード</a> — 別のオブジェクトを追従します。</li><li><a href="./Billboard.html">Billboardモード</a> — 常にターゲットの方向を向きます。</li><li><a href="./SmoothBillboard.html">SmoothBillboardモード</a> — なめらかにターゲット 方向を向きます。</li></ul><p><strong>物理エンジンで動きを決めるモード</strong> — 重力や衝突などの物理演算で 動きます。</p><ul><li><a href="./SimplePhysics.html">SimplePhysicsモード</a> — 剛体物理演算で動きます。</li><li><a href="./KinematicCharacter.html">KinematicCharacterモード</a> — カプセル コライダーによるキネマティックキャラクター制御です。</li><li><a href="./DynamicCharacter.html">DynamicCharacterモード</a> — カプセル コライダーによる動的キャラクター制御です。</li></ul><h2 id="物理演算の基本" tabindex="-1">物理演算の基本 <a class="header-anchor" href="#物理演算の基本" aria-label="Permalink to &quot;物理演算の基本&quot;">​</a></h2><p>a3jsの物理演算には<a href="https://rapier.rs/" target="_blank" rel="noreferrer">Rapier</a>という物理エンジンを 使っています。物理系のモードを使う前に、必ず物理エンジンの 初期化が必要です。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a3.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">initPhysics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>知っておくと役立つポイントをまとめます。</p><ul><li>物理演算の世界（物理ワールド）は <a href="./../Scene/">Sceneごとに独立</a>しています。重力はデフォルトで 下向き9.81m/s²です。</li><li>物理系のモードのオブジェクトを<code>setPosition()</code>で動かすことは できません。位置を強制的に変更するには<code>setPositionNow()</code>などの Nowがついたメソッドを使います（詳しくは <a href="./../MoveRotateScale/">移動・回転・拡大縮小について</a>）。</li><li>衝突を検知して処理を書くこともできます（詳しくは <a href="./../CollisionDetection/">当たり判定</a>）。</li><li>車の物理シミュレーションには専用の <a href="./../OtherFunctions/CarControl.html">CarControlクラス</a>があります。</li><li>コライダー（衝突判定の形状）の様子は <code>scene.setPhysicsDebugMode(true);</code>で可視化できます。</li></ul>',14)])])}const u=i(l,[["render",o]]);export{k as __pageData,u as default};
